            df4dx(8) = ((cos(x8)*sin(x9) - cos(x9)*sin(x7)*sin(x8))*(g + (c7 + c8)*(refzdot - x6 + lambda4*x16 + c7*(refz - x3)) + (refz - x3)*(- c7^2 + lambda4 + 1) - c7*lambda4*x16))/(cos(x7)*cos(x8)) + (sin(x8)*(sin(x8)*sin(x9) + cos(x8)*cos(x9)*sin(x7))*(g + (c7 + c8)*(refzdot - x6 + lambda4*x16 + c7*(refz - x3)) + (refz - x3)*(- c7^2 + lambda4 + 1) - c7*lambda4*x16))/(cos(x7)*cos(x8)^2);
            df4dx(9) = ((cos(x9)*sin(x8) - cos(x8)*sin(x7)*sin(x9))*(g + (c7 + c8)*(refzdot - x6 + lambda4*x16 + c7*(refz - x3)) + (refz - x3)*(- c7^2 + lambda4 + 1) - c7*lambda4*x16))/(cos(x7)*cos(x8));
            df4dx(16) = -((c7*lambda4 - lambda4*(c7 + c8))*(sin(x8)*sin(x9) + cos(x8)*cos(x9)*sin(x7)))/(cos(x7)*cos(x8));
