        function df6dx = df6dx(model, ~, ~)
            df6dx = zeros(1, model.numStates);

            c7 = model.c7; 
            c8 = model.c8;
            lambda4 = model.lambda4; 

            df6dx(3) = c7^2 - lambda4 - c7*(c7 + c8) - 1;
            df6dx(6) = - c7 - c8;
            df6dx(16) = lambda4*(c7 + c8) - c7*lambda4;
        end

