        function df12dp = df12dp(model, state, ref)
            df12dp = zeros(1, model.numParams);

            c5 = model.c5;
            lambda3 = model.lambda3;
            refpsi = ref.psi; 
            refpsidot = ref.psi_dot;

            x9 = state(9);
            x12 = state(12);
            x15 = state(15); 

            df12dp(5) = 2*refpsidot - 2*x12 + lambda3*x15 + 2*c5*(refpsi - x9);
            df12dp(15) = refpsi - x9 + c5*x15;
        end
        
        function df13dp = df13dp(model, state, ref)
            df13dp = zeros(1, model.numParams);

            refx = ref.x;
            refxdot = ref.x_dot;
            refxddot = ref.x_ddot;
            refz = ref.z;
            refzdot = ref.z_dot;

            c7 = model.c7; 
            c8 = model.c8;
            c9 = model.c9;
            c10 = model.c10;
            lambda4 = model.lambda4;
            lambda5 = model.lambda5;
            g = model.g;

            x1 = state(1);
            x3 = state(3);
            x4 = state(4);
            x6 = state(6);
            x7 = state(7);
            x8 = state(8);
            x16 = state(16);
            x17 = state(17);

            df13dp(7) = -(4*cos(x7)*cos(x8)*(refzdot - x6 + (c7 + c8)*(refz - x3) - c7*(refz - x3))*(refxddot + (c9 + c10)*(refxdot - x4 + lambda5*x17 + c9*(refx - x1)) + (refx - x1)*(- c9^2 + lambda5 + 1) - c9*lambda5*x17))/(g + (c7 + c8)*(refzdot - x6 + lambda4*x16 + c7*(refz - x3)) + (refz - x3)*(- c7^2 + lambda4 + 1) - c7*lambda4*x16)^2;
            df13dp(8) = -(4*cos(x7)*cos(x8)*(refxddot + (c9 + c10)*(refxdot - x4 + lambda5*x17 + c9*(refx - x1)) + (refx - x1)*(- c9^2 + lambda5 + 1) - c9*lambda5*x17)*(refzdot - x6 + lambda4*x16 + c7*(refz - x3)))/(g + (c7 + c8)*(refzdot - x6 + lambda4*x16 + c7*(refz - x3)) + (refz - x3)*(- c7^2 + lambda4 + 1) - c7*lambda4*x16)^2;
            df13dp(9) = (4*cos(x7)*cos(x8)*(refxdot - x4 + (c9 + c10)*(refx - x1) - c9*(refx - x1)))/(g + (c7 + c8)*(refzdot - x6 + lambda4*x16 + c7*(refz - x3)) + (refz - x3)*(- c7^2 + lambda4 + 1) - c7*lambda4*x16);
            df13dp(10) = (4*cos(x7)*cos(x8)*(refxdot - x4 + lambda5*x17 + c9*(refx - x1)))/(g + (c7 + c8)*(refzdot - x6 + lambda4*x16 + c7*(refz - x3)) + (refz - x3)*(- c7^2 + lambda4 + 1) - c7*lambda4*x16);
            df13dp(16) = -(4*cos(x7)*cos(x8)*(refxddot + (c9 + c10)*(refxdot - x4 + lambda5*x17 + c9*(refx - x1)) + (refx - x1)*(- c9^2 + lambda5 + 1) - c9*lambda5*x17)*(refz - x3 - c7*x16 + x16*(c7 + c8)))/(g + (c7 + c8)*(refzdot - x6 + lambda4*x16 + c7*(refz - x3)) + (refz - x3)*(- c7^2 + lambda4 + 1) - c7*lambda4*x16)^2;
            df13dp(17) = (4*cos(x7)*cos(x8)*(refx - x1 - c9*x17 + x17*(c9 + c10)))/(g + (c7 + c8)*(refzdot - x6 + lambda4*x16 + c7*(refz - x3)) + (refz - x3)*(- c7^2 + lambda4 + 1) - c7*lambda4*x16);
            df13dp(20) = -(4*cos(x7)*cos(x8)*(refxddot + (c9 + c10)*(refxdot - x4 + lambda5*x17 + c9*(refx - x1)) + (refx - x1)*(- c9^2 + lambda5 + 1) - c9*lambda5*x17))/(g + (c7 + c8)*(refzdot - x6 + lambda4*x16 + c7*(refz - x3)) + (refz - x3)*(- c7^2 + lambda4 + 1) - c7*lambda4*x16)^2;
        end
        
        function df14dp = df14dp(model, state, ref)
            df14dp = zeros(1, model.numParams);

            refy = ref.y;
            refydot = ref.y_dot;
