        function d2fdxdp = d2fdxdp(model, state, ref)
            d2fdxdp = zeros(model.numStates, model.numStates, model.numParams);

            d2fdxdp(4, :, :) = derivatives_drone_IB_syms.d2f4dxdp(model, state, ref);
            d2fdxdp(5, :, :) = derivatives_drone_IB_syms.d2f5dxdp(model, state, ref);
            d2fdxdp(6, :, :) = derivatives_drone_IB_syms.d2f6dxdp(model, state, ref);

            d2fdxdp(10, :, :) = derivatives_drone_IB_syms.d2f10dxdp(model, state, ref);
            d2fdxdp(11, :, :) = derivatives_drone_IB_syms.d2f11dxdp(model, state, ref);
            d2fdxdp(12, :, :) = derivatives_drone_IB_syms.d2f12dxdp(model, state, ref);

            d2fdxdp(13, :, :) = derivatives_drone_IB_syms.d2f13dxdp(model, state, ref);
            d2fdxdp(14, :, :) = derivatives_drone_IB_syms.d2f14dxdp(model, state, ref);
            
        end

        function d2f4dxdp = d2f4dxdp(model, state, ref)
            d2f4dxdp = zeros(model.numStates, model.numParams);

            refz = ref.z;
            refzdot = ref.z_dot;

            c7 = model.c7; 
            c8 = model.c8;
            lambda4 = model.lambda4; 

            x3 = state(3);
            x6 = state(6);
            x7 = state(7);
            x8 = state(8);
            x9 = state(9);
            x16 = state(16);

            d2f4dxdp(3,7)=-(c8*(sin(x8)*sin(x9) + cos(x8)*cos(x9)*sin(x7)))/(cos(x7)*cos(x8));
           d2f4dxdp(3,8)=-(c7*(sin(x8)*sin(x9) + cos(x8)*cos(x9)*sin(x7)))/(cos(x7)*cos(x8));
           d2f4dxdp(3,16)=-(sin(x8)*sin(x9) + cos(x8)*cos(x9)*sin(x7))/(cos(x7)*cos(x8));
           d2f4dxdp(6,7)=-(sin(x8)*sin(x9) + cos(x8)*cos(x9)*sin(x7))/(cos(x7)*cos(x8));
           d2f4dxdp(6,8)=-(sin(x8)*sin(x9) + cos(x8)*cos(x9)*sin(x7))/(cos(x7)*cos(x8));
