        function d2f12dxdp = d2f12dxdp(model, ~, ~)
            d2f12dxdp = zeros(model.numStates, model.numParams);

            c5 = model.c5;
            c6 = model.c6;
            lambda3 = model.lambda3;

            d2f12dxdp(9,5)=- 4*c5 - c6;
           d2f12dxdp(9,6)=-c5;
           d2f12dxdp(9,15)=-1;
           d2f12dxdp(12,5)=-1;
           d2f12dxdp(12,6)=-1;
           d2f12dxdp(15,6)=lambda3;
           d2f12dxdp(15,15)=c6;
        end
        
        
